import {Chess} from './vendor/chess.mjs';
import {JazzBand} from './jam-audio.mjs';
import {dailyScore,localDay,lastDays,uci,readTake,JAM_VERSION,JAM_LENGTH} from './jam.mjs';
const symbols={k:'♚',q:'♛',r:'♜',b:'♝',n:'♞',p:'♟'},names={k:'王',q:'后',r:'车',b:'象',n:'马',p:'兵'};
const replies=['第一句，乐队接住了。','黑白轮流说话，谁也不用赢。','这个转弯，有点意思。','走到一半，已经有你的味道。','国王没有意见，鼓手有点兴奋。','再两步，今天就有作品了。','最后一句，留给直觉。','掌声不用等别人，先送给自己。'];
export function createJam({pause,resume,identityReady}){
  document.body.insertAdjacentHTML('beforeend',`<dialog id="jam-dialog" class="jam-dialog" aria-labelledby="jam-title">
    <header class="jam-header"><span class="jam-kicker">棋间 · AFTER HOURS</span><button id="jam-close" class="jam-quiet">收工，回棋间 ×</button></header>
    <div class="jam-heading"><div><p id="jam-date" class="jam-kicker"></p><h2 id="jam-title"></h2><p id="jam-subtitle"></p></div><span class="jam-emblem" aria-hidden="true">♞<small>OFF<br>THE BOOK</small></span></div>
    <div class="jam-layout"><section><div class="jam-board-top"><strong id="jam-turn"></strong><span id="jam-meta"></span></div><div id="jam-board" class="board jam-board" role="group" aria-label="每日即兴棋盘"></div><div id="jam-promotions" class="jam-actions" hidden></div><p class="jam-how">你掌控黑白双方。点棋子，再点亮起的格子；八步编成一首小曲。</p></section>
    <section class="jam-desk"><div class="jam-desk-top"><span>今晚你领奏</span><button id="jam-sound" class="jam-quiet" aria-pressed="false">开启声音 ♪</button></div><div id="jam-bars" class="jam-bars" aria-label="演奏进度"></div><p id="jam-feedback" class="jam-feedback" role="status" aria-live="polite"></p>
    <div class="jam-actions"><button id="jam-blue" class="jam-blue" aria-pressed="false">下一步，加颗蓝音 ♭</button><button id="jam-help" class="jam-quiet">给我一个落点</button></div><p class="jam-fine">蓝音让下一句偏离半音，再落回旋律。规则照旧，耳朵放个假。</p>
    <div id="jam-finish" class="jam-finish" hidden><span class="jam-kicker">今日小样 / YOUR TAKE</span><h3>这几步，只有你这样走。</h3><p id="jam-finish-note"></p><div class="jam-actions"><button id="jam-replay" class="jam-primary">回听我的小曲 ▶</button><button id="jam-again" class="jam-quiet">再即兴一遍</button></div><p id="jam-save" class="jam-fine" role="status"></p><button id="jam-retry" class="jam-quiet" hidden>重试保存</button><button id="jam-download" class="jam-quiet">下载这段乐谱 ↓</button></div>
    <button id="jam-stop" class="jam-quiet" hidden>■ 停止回听</button>
    <div class="jam-week"><span class="jam-kicker">最近七天 · 来过就留一拍</span><div id="jam-days"></div><p class="jam-fine">缺席也没关系。乐队不会追问你昨天去了哪里。</p></div>
    <details class="jam-shelf"><summary>我的小唱片</summary><div id="jam-history"></div><p class="jam-fine">最近 30 段乐谱保存在服务器，以当前浏览器识别。回听会重新演奏走法，不录制麦克风。换设备或清除 Cookie 前，可下载乐谱留存。</p><button id="jam-import" class="jam-quiet">打开已下载的乐谱</button><input id="jam-import-file" type="file" accept=".json,application/json" hidden><button id="jam-library-retry" class="jam-quiet" hidden>重新读取唱片</button></details>
    </section></div><p class="jam-outro">输赢明天再说。今天，先让马跳一支舞。</p></dialog>`);
  const $=id=>document.getElementById(id),dialog=$('jam-dialog'),band=new JazzBand();
  let score=dailyScore(),game=new Chess(score.fen),moves=[],blue=[],selected=null,armed=false,pendingPromotion=null,done=false,take=null,records=[],saving=false,pending=false,playing=false,replayGame=null,replayRecord=null,replayIndex=-1,loadPromise=null,loaded=false,audioJob=0;
  function say(text){$('jam-feedback').textContent=text;}
  function soundLabel(){const enabled=band.enabled;$('jam-sound').textContent=enabled?'声音已开启 · 静音':'开启声音 ♪';$('jam-sound').setAttribute('aria-pressed',String(enabled));}
  function draw(){
    const b=replayGame||game,legal=!playing&&!done&&selected?game.moves({square:selected,verbose:true}):[],last=playing?b.history({verbose:true}).at(-1):moves.at(-1);
    $('jam-board').innerHTML=b.board().flat().map((p,i)=>{const sq='abcdefgh'[i%8]+(8-Math.floor(i/8)),light=(Math.floor(i/8)+i%8)%2===0,label=`${sq}${p?' '+(p.color==='w'?'白':'黑')+names[p.type]:' 空格'}${legal.some(m=>m.to===sq)?' 可走':''}`;return `<button class="square ${light?'light':'dark'} ${p?'occupied':''} ${selected===sq?'selected':''} ${legal.some(m=>m.to===sq)?'legal':''} ${last&&(last.from===sq||last.to===sq)?'last-move':''}" data-jam-square="${sq}" aria-label="${label}" ${done||playing?'disabled':''}>${p?`<span class="piece ${p.color==='w'?'white':'black'}" aria-hidden="true">${symbols[p.type]}</span>`:''}${i%8===0?`<span class="coordinate rank">${8-Math.floor(i/8)}</span>`:''}${i>=56?`<span class="coordinate file">${'abcdefgh'[i%8]}</span>`:''}</button>`;}).join('');
    $('jam-turn').textContent=playing?'正在回听 · 第 '+(replayIndex+1)+' 句':done?'今日即兴完成':(game.turn()==='w'?'白方':'黑方')+'领奏'+(game.isCheck()?' · 国王被将军，请先解围':'');
    const count=playing?replayRecord.moves.length:moves.length,blueNotes=playing?replayRecord.blue:blue;
    $('jam-bars').innerHTML=Array.from({length:JAM_LENGTH},(_,i)=>`<span class="${i<count?'filled':''} ${playing&&i===replayIndex?'sounding':''}" aria-label="第${i+1}步${i<count?'已完成':'待演奏'}">${i<count?(blueNotes.includes(i)?'♭':'♪'):i+1}</span>`).join('');
    $('jam-blue').disabled=done||playing;$('jam-help').disabled=done||playing;$('jam-blue').setAttribute('aria-pressed',String(armed));$('jam-blue').textContent=armed?'蓝音就绪 · 点此取消 ♭':'下一步，加颗蓝音 ♭';
    $('jam-replay').disabled=playing;$('jam-again').disabled=saving||pending||playing;$('jam-finish').hidden=!done;$('jam-stop').hidden=!playing;
    $('jam-promotions').hidden=!pendingPromotion;$('jam-promotions').innerHTML=pendingPromotion?['q','r','b','n'].map(p=>`<button class="jam-quiet" data-jam-promote="${p}">升变为${names[p]}</button>`).join(''):'';
  }
  function header(){const current=dailyScore();$('jam-date').textContent=score.day+' / 每日即兴';$('jam-title').textContent=score.title;$('jam-subtitle').textContent=score.line;$('jam-meta').textContent=`${score.key} 调 · ${score.tempo} BPM`;$('jam-entry-date').textContent=`${current.title} · ${current.key} 调`;$('jam-entry-copy').textContent=current.line;}
  function history(){
    $('jam-days').innerHTML=lastDays().map(day=>`<span class="${records.some(r=>r.day===day)?'visited':''}" title="${day}" aria-label="${day} ${records.some(r=>r.day===day)?'已演奏':'未演奏'}"><b>${records.some(r=>r.day===day)?'♪':'·'}</b>${day.slice(5).replace('-','/')}</span>`).join('');
    $('jam-history').innerHTML=records.length?records.slice(0,30).map((r,i)=>`<button class="jam-record" data-jam-record="${i}" ${playing?'disabled':''}><span>${r.day.slice(5).replace('-','/')} · ${dailyScore(r.day).title}</span><span>回听 ↗</span></button>`).join(''):`<p class="jam-fine">${loaded?'还没有小唱片。你的第一段，等这八步。':'唱片还没读到，你可以先玩。'}</p>`;
  }
  async function api(body){const response=await fetch('/api/jams',{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(12000)});const data=await response.json();if(!response.ok)throw new Error(data.error||'暂时无法读取');return data;}
  function accept(data){records=data.takes.map(t=>readTake(t).take);loaded=true;history();}
  async function load(){if(loadPromise)return loadPromise;loadPromise=(async()=>{try{await identityReady;accept(await api());$('jam-library-retry').hidden=true;}catch{$('jam-library-retry').hidden=false;}finally{loadPromise=null;history();}})();return loadPromise;}
  async function save(){if(saving||!take)return;saving=true;pending=true;$('jam-save').textContent='正在把这段即兴放上唱片架…';$('jam-retry').hidden=true;draw();try{await loadPromise;await identityReady;accept(await api(take));pending=false;$('jam-save').textContent='已保存。明天来，会有另一份曲谱。';}catch{$('jam-save').textContent='还没保存成功，乐谱仍留在这页。请重试或先下载。';$('jam-retry').hidden=false;}finally{saving=false;draw();}}
  function complete(){done=true;take={id:crypto.randomUUID(),version:JAM_VERSION,day:score.day,moves:moves.map(uci),blue:[...blue]};$('jam-finish-note').textContent=game.isGameOver()&&moves.length<8?'棋局提前落幕，乐队也给你一个漂亮的收尾。':`八步已编成约 ${Math.round(moves.length*240/score.tempo+2)} 秒的小曲。你负责走法，乐队负责和声。`;save();}
  function playMove(m){pendingPromotion=null;const move=game.move(m),i=moves.length;moves.push(move);if(armed)blue.push(i);band.live(score,move,i,armed);say(armed?'这一颗蓝音，故意歪一点，也能落回来。':replies[i]);armed=false;selected=null;if(moves.length===JAM_LENGTH||game.isGameOver())complete();draw();}
  $('jam-board').onclick=e=>{const cell=e.target.closest('[data-jam-square]');if(!cell||done||playing)return;const sq=cell.dataset.jamSquare,candidates=selected?game.moves({square:selected,verbose:true}).filter(m=>m.to===sq):[];if(candidates.length){if(candidates.some(m=>m.promotion)){pendingPromotion={from:selected,to:sq};draw();say('兵走到了底线。为它选一件新乐器。');}else playMove({from:selected,to:sq});return;}pendingPromotion=null;const p=game.get(sq);selected=p?.color===game.turn()&&selected!==sq?sq:null;draw();if(selected)$('jam-board').querySelector(`[data-jam-square="${sq}"]`)?.focus({preventScroll:true});};
  $('jam-promotions').onclick=e=>{const p=e.target.dataset.jamPromote;if(p&&pendingPromotion)playMove({...pendingPromotion,promotion:p});};
  $('jam-help').onclick=()=>{const legal=game.moves({verbose:true}),m=legal[(moves.length*7+score.tempo)%legal.length];if(!m)return;selected=m.from;pendingPromotion=null;draw();say(`试试 ${m.from} → ${m.to}？这是一个合法落点，不是标准答案。`);$('jam-board').querySelector(`[data-jam-square="${m.to}"]`)?.focus({preventScroll:true});};
  $('jam-blue').onclick=()=>{armed=!armed;draw();};
  function stop(){audioJob++;band.stop();playing=false;replayGame=null;replayRecord=null;replayIndex=-1;draw();history();}
  $('jam-stop').onclick=()=>{stop();say('暂停在这里，也是一种节奏。');};
  $('jam-sound').onclick=async()=>{const job=++audioJob;if(band.enabled){stop();band.mute();soundLabel();say('静音即兴。乐谱依然会记住你的走法。');return;}try{await band.enable();if(job!==audioJob||!dialog.open){band.mute();return;}soundLabel();say('乐队就位。走一步，听听它怎么接。');}catch(e){say(e.message);soundLabel();}};
  async function replay(record){stop();const job=++audioJob;try{const validated=readTake(record);await band.enable();if(job!==audioJob||!dialog.open){band.mute();return;}soundLabel();playing=true;selected=null;pendingPromotion=null;replayRecord=validated.take;replayGame=new Chess(dailyScore(record.day).fen);replayIndex=-1;draw();history();say('正在演奏 '+record.day+' 的小曲。');band.replay(dailyScore(record.day),validated.moves,record.blue,i=>{while(replayGame.history().length<=i){const m=validated.moves[replayGame.history().length];replayGame.move({from:m.from,to:m.to,...(m.promotion?{promotion:m.promotion}:{})});}replayIndex=i;draw();},()=>{stop();say('这一版，只属于刚才的你。');});}catch(e){stop();say(e.message);}}
  $('jam-replay').onclick=()=>replay(take);$('jam-history').onclick=e=>{const button=e.target.closest('[data-jam-record]');if(button)replay(records[+button.dataset.jamRecord]);};
  function reset(){stop();score=dailyScore();game=new Chess(score.fen);moves=[];blue=[];selected=null;armed=false;pendingPromotion=null;done=false;take=null;pending=false;header();say('八步就好。先选一枚白棋，让乐队听见你的第一句。');draw();}
  $('jam-again').onclick=reset;$('jam-retry').onclick=save;$('jam-library-retry').onclick=load;
  $('jam-import').onclick=()=>$('jam-import-file').click();$('jam-import-file').onchange=async()=>{const file=$('jam-import-file').files[0];if(!file)return;try{if(file.size>3000)throw new Error('请选择从棋间下载的乐谱（最多 3 KB）。');const record=JSON.parse(await file.text());if(record.format!=='knight-room-jam')throw new Error('这不是棋间的乐谱文件。');const checked=readTake(record).take;records=[checked,...records.filter(r=>r.id!==checked.id)].slice(0,30);history();say('乐谱已放入本次唱片列表，点「回听」即可演奏。');}catch(e){say(e.message);}finally{$('jam-import-file').value='';}};
  $('jam-download').onclick=()=>{if(!take)return;const url=URL.createObjectURL(new Blob([JSON.stringify({format:'knight-room-jam',...take},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`knight-room-jam-${take.day}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  $('jam-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{stop();band.mute();soundLabel();resume();});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();band.mute();soundLabel();if(dialog.open)say('你离开时，乐队也休息了。回来后可重新开启声音。');}});
  window.addEventListener('pagehide',()=>band.mute());
  function open(){if(dialog.open)return;if(score.day!==localDay()&&(!moves.length||done&&!pending))reset();pause();header();draw();history();dialog.showModal();load();}
  $('jam-open').onclick=open;header();say('八步就好。先选一枚白棋，让乐队听见你的第一句。');return {open};
}
